/**
 * src/pnl-card.mjs
 * Shareable PnL card. Meme Checker's own visual identity — not a Phanes copy.
 *
 * Two surfaces, one data model:
 *   renderPnlText()  — a Telegram HTML message (always available, no deps)
 *   renderPnlSvg()   — a self-contained SVG that is rasterised to PNG and sent
 *                      with sendPhoto for the "shareable image" experience
 *
 * The SVG is generated by hand (no chart library, no headless browser) so the
 * bot has zero new runtime dependencies and the image is deterministic.
 *
 * HONESTY IN THE IMAGE ITSELF
 *   - "peak" is labelled "Peak (since call)" and the caption says it is not ATH
 *   - ROI is labelled as a price ratio, not profit
 *   - a call with no observation after entry shows "not observed yet" rather
 *     than a 1.0x that would read as "flat"
 */

import { fmtUsd } from './card-layout.mjs';
import { callMetrics, fmtMultiple, fmtSignedPercent } from './calls.mjs';

/** Age labels read naturally: "just now", not "just now ago". */
function ageText(label) {
  if (!label) return '—';
  return /just now/i.test(label) ? 'just now' : `${label} ago`;
}

function esc(v) {
  if (v == null) return '';
  return String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function escXml(v) {
  if (v == null) return '';
  return String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&apos;');
}

/** Truncate a display string by code points, not bytes. */
function clip(s, n) {
  if (!s) return '';
  const chars = [...String(s)];
  return chars.length <= n ? chars.join('') : `${chars.slice(0, n - 1).join('')}…`;
}

/** Colour for a multiple. Purely presentational. */
export function roiTone(mult) {
  if (!Number.isFinite(mult)) return { fill: '#8fa3b8', label: 'unknown' };
  if (mult >= 2) return { fill: '#2ecc71', label: 'up' };
  if (mult >= 1.05) return { fill: '#7ed321', label: 'up-small' };
  if (mult >= 0.95) return { fill: '#c9d1d9', label: 'flat' };
  if (mult >= 0.5) return { fill: '#f0a02a', label: 'down' };
  return { fill: '#e74c3c', label: 'down-big' };
}

/**
 * The Telegram text card. Kept short enough to be a photo caption.
 */
export function renderPnlText(call, { now = Date.now(), tokenName = null } = {}) {
  const m = callMetrics(call, now);
  const name = clip(tokenName ?? call.name ?? call.symbol ?? 'Token', 32);
  const symbol = call.symbol ? `$${clip(call.symbol, 14)}` : '';
  const tone = roiTone(m.currentMultiple);

  const lines = [];
  lines.push(`📊 <b>PnL — ${esc(name)}</b>${symbol ? ` <code>${esc(symbol)}</code>` : ''}`);
  lines.push('');

  // Caller + age
  const who = call.callerUsername ? `@${call.callerUsername}` : (call.callerName ?? 'unknown caller');
  lines.push(`👤 Called by <b>${esc(who)}</b> · ${esc(ageText(m.ageLabel))}`);
  lines.push('');

  lines.push(`Entry MC:  ${esc(fmtUsd(m.entryMarketCapUsd) ?? '—')}`);
  if (m.currentMarketCapUsd != null) {
    lines.push(`Current MC: ${esc(fmtUsd(m.currentMarketCapUsd))}`);
  } else {
    lines.push('Current MC: <i>not observed yet</i>');
  }

  // Peak is explicitly since-call, never ATH.
  if (m.peakIsObserved) {
    lines.push(`Peak MC:   ${esc(fmtUsd(m.peakMarketCapUsd))} <i>(since call)</i>`);
  } else {
    lines.push(`Peak MC:   <i>no higher observation since call</i>`);
  }
  lines.push('');

  if (m.currentMultiple != null) {
    const mult = fmtMultiple(m.currentMultiple);
    const pct = fmtSignedPercent(m.currentPercent);
    lines.push(`${tone.label === 'down' || tone.label === 'down-big' ? '🔻' : '📈'} <b>ROI: ${esc(mult)} (${esc(pct)})</b>`);
  } else {
    lines.push('ROI: <i>unavailable</i>');
  }
  if (m.peakIsObserved && m.peakMultiple != null) {
    lines.push(`Peak ROI: <b>${esc(fmtMultiple(m.peakMultiple))}</b> (${esc(fmtSignedPercent(m.peakPercent))})`);
  }
  if (m.drawdownFromPeak != null && m.peakIsObserved && m.drawdownFromPeak < -1) {
    lines.push(`From peak: ${esc(fmtSignedPercent(m.drawdownFromPeak))}`);
  }

  lines.push('');
  lines.push('<i>Price ratio since the call — not realized profit. Peak is the highest observed since this call, not all-time high.</i>');
  lines.push(`⚡ <i>Meme Checker</i>`);
  return lines.join('\n');
}

/**
 * Self-contained 800x500 SVG. Rasterised to PNG by the caller if a rasteriser is
 * available; the SVG itself is a valid image Telegram accepts as a document.
 */
export function renderPnlSvg(call, { now = Date.now(), tokenName = null } = {}) {
  const m = callMetrics(call, now);
  const name = clip(tokenName ?? call.name ?? call.symbol ?? 'Token', 26);
  const symbol = call.symbol ? `$${clip(call.symbol, 12)}` : '';
  const tone = roiTone(m.currentMultiple);
  const W = 800, H = 500;

  const who = call.callerUsername ? `@${call.callerUsername}` : (call.callerName ?? 'unknown caller');

  const rows = [
    ['Entry MC', fmtUsd(m.entryMarketCapUsd) ?? '—', '#c9d1d9'],
    ['Current MC', m.currentMarketCapUsd != null ? fmtUsd(m.currentMarketCapUsd) : 'not observed', '#c9d1d9'],
    ['Peak MC (since call)', m.peakIsObserved ? (fmtUsd(m.peakMarketCapUsd) ?? '—') : 'no higher observation', '#c9d1d9'],
  ];

  const rowSvg = rows.map((r, i) => {
    const y = 300 + i * 46;
    return `
    <text x="56" y="${y}" font-family="SF Mono, Consolas, monospace" font-size="19" fill="#8fa3b8">${escXml(r[0])}</text>
    <text x="744" y="${y}" text-anchor="end" font-family="SF Mono, Consolas, monospace" font-size="19" fill="${r[2]}">${escXml(r[1])}</text>`;
  }).join('');

  const roiText = m.currentMultiple != null ? fmtMultiple(m.currentMultiple) : 'n/a';
  const roiPct = m.currentMultiple != null ? fmtSignedPercent(m.currentPercent) : '';
  const peakText = (m.peakIsObserved && m.peakMultiple != null) ? fmtMultiple(m.peakMultiple) : null;

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#121a24"/>
      <stop offset="100%" stop-color="#0b1118"/>
    </linearGradient>
    <linearGradient id="accent" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stop-color="#6ab3f3"/>
      <stop offset="100%" stop-color="#9b6af3"/>
    </linearGradient>
  </defs>

  <rect width="${W}" height="${H}" fill="url(#bg)"/>
  <rect x="0" y="0" width="${W}" height="5" fill="url(#accent)"/>

  <!-- brand -->
  <text x="56" y="66" font-family="-apple-system, Segoe UI, Roboto, sans-serif" font-size="21" font-weight="700" fill="#ffffff">MEME CHECKER</text>
  <text x="56" y="90" font-family="-apple-system, Segoe UI, Roboto, sans-serif" font-size="13" fill="#6ab3f3" letter-spacing="2">CALL PERFORMANCE</text>
  <text x="744" y="66" text-anchor="end" font-family="-apple-system, Segoe UI, Roboto, sans-serif" font-size="14" fill="#8fa3b8">${escXml(m.ageLabel ?? '')} ago</text>

  <!-- token -->
  <text x="56" y="176" font-family="-apple-system, Segoe UI, Roboto, sans-serif" font-size="38" font-weight="700" fill="#ffffff">${escXml(name)}</text>
  <text x="56" y="208" font-family="SF Mono, Consolas, monospace" font-size="17" fill="#8fa3b8">${escXml(symbol)} · ${escXml(call.chain ?? '')}</text>

  <!-- big ROI -->
  <text x="744" y="176" text-anchor="end" font-family="-apple-system, Segoe UI, Roboto, sans-serif" font-size="56" font-weight="700" fill="${tone.fill}">${escXml(roiText)}</text>
  <text x="744" y="206" text-anchor="end" font-family="SF Mono, Consolas, monospace" font-size="18" fill="${tone.fill}">${escXml(roiPct)}</text>

  <!-- caller -->
  <text x="56" y="252" font-family="-apple-system, Segoe UI, Roboto, sans-serif" font-size="16" fill="#c9d1d9">Called by ${escXml(who)}</text>
  ${peakText ? `<text x="744" y="252" text-anchor="end" font-family="SF Mono, Consolas, monospace" font-size="16" fill="#8fa3b8">peak ${escXml(peakText)}</text>` : ''}

  <line x1="56" y1="272" x2="744" y2="272" stroke="#22303d" stroke-width="1"/>
  ${rowSvg}

  <!-- disclaimer -->
  <text x="56" y="462" font-family="-apple-system, Segoe UI, Roboto, sans-serif" font-size="12" fill="#5d7387">Price ratio since the call, not realized profit. Peak = highest observed since this call, not all-time high.</text>
</svg>`;
}
